/*IF( Data_Quality_Score__c =100,"All Contract Details Captured", "Missing: "&IF( LEN( TEXT(MONTH( StartDate ))) = 0, "Contract Start Date, ","")&""&IF(LEN( TEXT(ContractTerm)) = 0, "Contract Term, ","")&""&IF( LEN( BillingCity ) = 0, "Complete Contract Address, ","")&""&IF(LEN( CustomerSignedId ) = 0, "Customer Signature, ","")&""&IF( ISPICKVAL( OwnerExpirationNotice ,""), "Owner Expiration Notice",""))*/
IF( RecordType.DeveloperName="ER_Client_Contract_RT",
IF( Data_Quality_Score__c>98,"All Contract Details Captured", "Missing: "& IF(LEN(CustomerSignedId)=0,"Customer Signed By,","") &IF(AND(NOT(ISPICKVAL(Account.ER_Status__c,"Active")),LEN( TEXT(MONTH(EndDate)))=0),"Account not active and no contract end date,","") &IF(AND(NOT(ER_WS_Message__c="succeeded"),LEN(ER_Card_Operational_System_ID__c&ER_Paper_Operational_System_ID__c)=0),"Operational System ID missing and no synchronization,","") &IF(OR(ISPICKVAL(ER_InvoicingFrequency2__c,""),ISPICKVAL(ER_PaymentTerms2__c,"")),"Inv. Freq. or payment term,","") &IF(ISPICKVAL(ER_PaymentMethod2__c,""),"Payment Method,","") )
, IF( Data_Quality_Score__c>98,"All Contract Details Captured", "Missing: "& IF(LEN(CustomerSignedId)=0,"Customer Signed By,","") &IF(AND(NOT(ISPICKVAL(Account.ER_Status__c,"Active")),LEN( TEXT(MONTH(EndDate)))=0),"Account not active and no contract end date,","") &IF(AND(NOT(ER_WS_Message__c="succeeded"),LEN(ER_Card_Operational_System_ID__c&ER_Paper_Operational_System_ID__c)=0),"Operational System ID missing and no synchronization,","") &IF(OR(ISPICKVAL(ER_InvoicingFrequency2__c,""),ISPICKVAL(ER_PaymentTerms2__c,""),ISPICKVAL(ER_ReimbursementTerm2__c,"")),"Inv. Freq., Reimb. or payment term,","") &IF(ISPICKVAL(ER_PaymentMethod2__c,""),"Payment Method,","") )
)
